    private final MainActivity app;private final Handler main=new Handler(Looper.getMainLooper());private final HandlerThread cameraThread=new HandlerThread("qiban-camera");private final Handler cameraHandler;
    private final AmbientSound ambient;private boolean wantedHearing=false,pendingHearing=false,foreground=true;private volatile String sound="";private volatile long soundAt=0;private final java.util.concurrent.atomic.AtomicInteger asrGeneration=new java.util.concurrent.atomic.AtomicInteger();
