    private void image(ImageReader source){try(Image image=source.acquireLatestImage()){if(image==null)return;ByteBuffer buffer=image.getPlanes()[0].getBuffer();byte[] bytes=new byte[buffer.remaining()];buffer.get(bytes);CompletableFuture<Snapshot> request=captured;captured=null;if(request==null)return;Bitmap raw=BitmapFactory.decodeByteArray(bytes,0,bytes.length);if(raw==null){request.completeExceptionally(new IOException("镜头画面未能解码。"));return;}int width=raw.getWidth(),height=raw.getHeight();float ratio=Math.min(1f,1024f/Math.max(width,height));Bitmap small=ratio<1?Bitmap.createScaledBitmap(raw,Math.max(1,(int)(width*ratio)),Math.max(1,(int)(height*ratio)),true):raw;ByteArrayOutputStream out=new ByteArrayOutputStream();small.compress(Bitmap.CompressFormat.JPEG,78,out);String base64=android.util.Base64.encodeToString(out.toByteArray(),android.util.Base64.NO_WRAP);labeler.process(InputImage.fromBitmap(small,0)).addOnSuccessListener(labels->{String text=labels.stream().limit(8).map(l->l.getText()+" ("+Math.round(l.getConfidence()*100)+"%)").collect(java.util.stream.Collectors.joining(", "));request.complete(new Snapshot(base64,text));small.recycle();if(raw!=small)raw.recycle();}).addOnFailureListener(error->{request.complete(new Snapshot(base64,""));small.recycle();if(raw!=small)raw.recycle();});}catch(Exception e){CompletableFuture<Snapshot> request=captured;captured=null;if(request!=null)request.completeExceptionally(e);}}
    Snapshot snapshot()throws Exception {if(camera==null||session==null)return null;CompletableFuture<Snapshot> result=new CompletableFuture<>();captured=result;cameraHandler.post(()->{try{CameraDevice c=camera;if(c==null)throw new IOException("镜头已关闭。");CaptureRequest.Builder request=c.createCaptureRequest(CameraDevice.TEMPLATE_STILL_CAPTURE);request.addTarget(reader.getSurface());int rotation=app.getWindowManager().getDefaultDisplay().getRotation()*90;request.set(CaptureRequest.JPEG_ORIENTATION,(sensorOrientation-rotation+360)%360);request.set(CaptureRequest.JPEG_QUALITY,(byte)80);session.capture(request.build(),null,cameraHandler);}catch(Exception e){captured=null;result.completeExceptionally(e);}});try{return result.get(10,TimeUnit.SECONDS);}finally{if(captured==result)captured=null;}}
    private void pauseCamera(){if(session!=null){session.close();session=null;}CameraDevice c=camera;camera=null;if(c!=null)c.close();if(reader!=null){reader.close();reader=null;}if(previewSurface!=null){previewSurface.release();previewSurface=null;}if(cameraFrame!=null){app.overlay().removeView(cameraFrame);cameraFrame=null;preview=null;}CompletableFuture<Snapshot> pending=captured;captured=null;if(pending!=null)pending.cancel(true);app.homeEvent(MainActivity.json("type","camera","enabled",false));}
    void voiceCall(boolean enabled){wantedVoice=enabled;if(!enabled){pendingVoice=false;stopListening();app.homeEvent(MainActivity.json("type","voiceCall","enabled",false));return;}if(app.checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){pendingVoice=true;app.requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},302);return;}app.homeEvent(MainActivity.json("type","voiceCall","enabled",true));listen();}
    void replyFinished(){main.postDelayed(()->{if(!foreground||!wantedVoice||listening||recording.get())return;if(app.conversation.busy()||app.speech.isBusy()){replyFinished();return;}listen();},700);}
    String localVision(String dataURL)throws Exception {
        if(dataURL==null||dataURL.isEmpty()){Snapshot current=snapshot();if(current==null)throw new IOException("请先选一张照片或开启后置镜头。");return current.labels.isEmpty()?"本机未识别出可靠标签。":current.labels;}
        if(!dataURL.startsWith("data:image/jpeg;base64,")||dataURL.length()>5_000_000)throw new IOException("图片无效或过大。");byte[] bytes=android.util.Base64.decode(dataURL.substring(dataURL.indexOf(',')+1),android.util.Base64.DEFAULT);Bitmap bitmap=BitmapFactory.decodeByteArray(bytes,0,bytes.length);if(bitmap==null||bitmap.getWidth()>2048||bitmap.getHeight()>2048)throw new IOException("图片尺寸无效。");CompletableFuture<String> result=new CompletableFuture<>();labeler.process(InputImage.fromBitmap(bitmap,0)).addOnSuccessListener(labels->{result.complete(labels.isEmpty()?"本机未识别出可靠标签。":labels.stream().limit(8).map(l->l.getText()+"（"+Math.round(l.getConfidence()*100)+"%）").collect(java.util.stream.Collectors.joining("\n")));bitmap.recycle();}).addOnFailureListener(error->{result.completeExceptionally(error);bitmap.recycle();});return result.get(20,TimeUnit.SECONDS);
    }
    void listen(){if(listening||recording.get()){stopListening();return;}if(app.checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){app.requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},302);return;}ambient.stop();app.speech.stop();audioWorker.execute(()->{try{JSONObject remote=app.network.service("asr");if(remote!=null&&remote.optBoolean("enabled")){remoteRecord(remote);return;}main.post(this::systemListen);}catch(Exception e){app.notice(e.getMessage());}});}
    private void systemListen(){if(!SpeechRecognizer.isRecognitionAvailable(app)){app.notice("手机没有系统识别服务，可在独立接口中配置 ASR。");return;}listening=true;boolean offline=Build.VERSION.SDK_INT>=31&&SpeechRecognizer.isOnDeviceRecognitionAvailable(app);recognizer=offline?SpeechRecognizer.createOnDeviceSpeechRecognizer(app):SpeechRecognizer.createSpeechRecognizer(app);recognizer.setRecognitionListener(new RecognitionListener(){public void onReadyForSpeech(Bundle p){app.homeEvent(MainActivity.json("type","listening","value",true,"mode",offline?"本机离线识别":"系统识别 · 优先离线"));}public void onBeginningOfSpeech(){}public void onRmsChanged(float rms){app.homeEvent(MainActivity.json("type","sound","label",rms>4?"正在说话":"倾听中"));}public void onBufferReceived(byte[] b){}public void onEndOfSpeech(){}public void onError(int error){wantedVoice=false;app.homeEvent(MainActivity.json("type","voiceCall","enabled",false));finishRecognition();app.notice("语音识别未完成："+error+"。可重试或配置独立 ASR。");}public void onResults(Bundle result){ArrayList<String> values=result.getStringArrayList(SpeechRecognizer.RESULTS_RECOGNITION);finishRecognition();if(values!=null&&!values.isEmpty())app.homeEvent(MainActivity.json("type","transcript","text",values.get(0)));}public void onPartialResults(Bundle result){}public void onEvent(int type,Bundle p){}});Intent intent=new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH).putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM).putExtra(RecognizerIntent.EXTRA_LANGUAGE,"zh-CN").putExtra(RecognizerIntent.EXTRA_PREFER_OFFLINE,true).putExtra(RecognizerIntent.EXTRA_PARTIAL_RESULTS,false);recognizer.startListening(intent);}
    private void finishRecognition(){listening=false;if(recognizer!=null){recognizer.destroy();recognizer=null;}app.homeEvent(MainActivity.json("type","listening","value",false));resumeHearing();}
    private void remoteRecord(JSONObject profile)throws Exception {if(app.checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED)throw new IOException("请先允许麦克风权限。");int ticket=asrGeneration.incrementAndGet();if(!recording.compareAndSet(false,true))return;int min=AudioRecord.getMinBufferSize(16000,AudioFormat.CHANNEL_IN_MONO,AudioFormat.ENCODING_PCM_16BIT);AudioRecord audio=new AudioRecord(MediaRecorder.AudioSource.VOICE_RECOGNITION,16000,AudioFormat.CHANNEL_IN_MONO,AudioFormat.ENCODING_PCM_16BIT,Math.max(min,8192));recorder=audio;ByteArrayOutputStream pcm=new ByteArrayOutputStream();try{audio.startRecording();app.homeEvent(MainActivity.json("type","listening","value",true,"mode","独立 ASR · 最长30秒，再次点击结束"));byte[] buffer=new byte[4096];boolean heard=false;long silence=System.currentTimeMillis();while(recording.get()&&pcm.size()<16000*2*30){int n=audio.read(buffer,0,Math.min(buffer.length,16000*2*30-pcm.size()));if(n<0)throw new IOException("录音中断。");pcm.write(buffer,0,n);double energy=0;for(int i=0;i+1<n;i+=2){short sample=(short)((buffer[i]&255)|(buffer[i+1]<<8));energy+=(double)sample*sample;}double rms=Math.sqrt(energy/Math.max(1,n/2));if(rms>420){heard=true;silence=System.currentTimeMillis();}else if(heard&&wantedVoice&&System.currentTimeMillis()-silence>900)break;}}finally{recording.set(false);recorder=null;audio.release();app.homeEvent(MainActivity.json("type","listening","value",false));}if(ticket!=asrGeneration.get()||!foreground||pcm.size()<3200)return;
        ByteBuffer wav=ByteBuffer.allocate(44+pcm.size()).order(ByteOrder.LITTLE_ENDIAN);wav.put("RIFF".getBytes(StandardCharsets.US_ASCII)).putInt(36+pcm.size()).put("WAVEfmt ".getBytes(StandardCharsets.US_ASCII)).putInt(16).putShort((short)1).putShort((short)1).putInt(16000).putInt(32000).putShort((short)2).putShort((short)16).put("data".getBytes(StandardCharsets.US_ASCII)).putInt(pcm.size()).put(pcm.toByteArray());String boundary="qiban-"+UUID.randomUUID();ByteArrayOutputStream body=new ByteArrayOutputStream();if(profile.optString("apiProtocol").equals("openAITranscription")){body.write(("--"+boundary+"\r\nContent-Disposition: form-data; name=\"model\"\r\n\r\n"+profile.optString("model")+"\r\n--"+boundary+"\r\nContent-Disposition: form-data; name=\"response_format\"\r\n\r\njson\r\n").getBytes(StandardCharsets.UTF_8));}body.write(("--"+boundary+"\r\nContent-Disposition: form-data; name=\"file\"; filename=\"speech.wav\"\r\nContent-Type: audio/wav\r\n\r\n").getBytes(StandardCharsets.UTF_8));body.write(wav.array());body.write(("\r\n--"+boundary+"--\r\n").getBytes(StandardCharsets.UTF_8));String result=new JSONObject(new String(app.network.exchange(app.network.serviceURL(profile),Map.of("Authorization","Bearer "+app.network.key(profile),"Content-Type","multipart/form-data; boundary="+boundary),body.toByteArray(),"POST",64000),StandardCharsets.UTF_8)).getString("text");app.homeEvent(MainActivity.json("type","transcript","text",result));main.post(this::resumeHearing);}
    void stopListening(){recording.set(false);if(recognizer!=null){recognizer.cancel();finishRecognition();}}
    void permissions(int request,int[] grants){boolean granted=grants.length>0&&grants[0]==PackageManager.PERMISSION_GRANTED;if(request==301&&permissionCamera!=null){CompletableFuture<Boolean> result=permissionCamera;permissionCamera=null;if(granted&&wanted)open(result);else{wanted=false;result.complete(false);}}if(request==302){if(pendingVoice){pendingVoice=false;voiceCall(granted);}else if(pendingHearing){pendingHearing=false;wantedHearing=granted;if(granted)resumeHearing();app.homeEvent(MainActivity.json("type","hearing","enabled",wantedHearing));}else if(granted)listen();}}
    void pause(){foreground=false;if(permissionCamera==null)wanted=false;wantedVoice=false;app.homeEvent(MainActivity.json("type","voiceCall","enabled",false));asrGeneration.incrementAndGet();ambient.stop();stopListening();pauseCamera();}
    void resume(){foreground=true;resumeHearing();if(wanted&&camera==null&&app.checkSelfPermission(Manifest.permission.CAMERA)==PackageManager.PERMISSION_GRANTED){CompletableFuture<Boolean> result=new CompletableFuture<>();result.exceptionally(error->{app.notice(error.getMessage());return false;});open(result);}}
    public void close(){wanted=false;wantedHearing=false;pause();ambient.close();cameraThread.quitSafely();audioWorker.shutdownNow();labeler.close();}
